  outline: 2px solid var(--vivo); outline-offset: -2px;
  background: rgba(var(--vivo-rgb),0.20) !important;
  box-shadow: inset 0 0 0 1px rgba(var(--vivo-rgb),0.35), 0 4px 14px rgba(0,0,0,0.45) !important;
  transform: scale(1.06); transition: transform .12s cubic-bezier(.2,.8,.2,1);
}
/* O aviso do arrastar: quanto entrou na mochila, ou por que não entrou.
   Pílula de couro no rodapé, some sozinha (3,2s). */
#root .menestrel-ui .inv-aviso {
  position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%); z-index: 80;
  display: flex; align-items: center; gap: 10px; max-width: min(520px, calc(100vw - 32px));
  padding: 10px 18px; border-radius: 999px;
  background: rgba(28,19,8,0.97); border: 1px solid rgba(var(--ouro-rgb),0.35);
  box-shadow: 0 10px 30px rgba(0,0,0,0.55);
  color: var(--tinta); font-family: var(--font-body); font-size: var(--fs-sm); line-height: 1.4;
  animation: inv-aviso-entra .22s cubic-bezier(.2,.8,.2,1);
}
#root .menestrel-ui .inv-aviso i { font-size: var(--fs-md); line-height: 1; flex-shrink: 0; color: var(--vivo); }
#root .menestrel-ui .inv-aviso--recusa { border-color: rgba(224,138,111,0.45); }
#root .menestrel-ui .inv-aviso--recusa i { color: #E08A6F; }
@keyframes inv-aviso-entra { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }
@media (prefers-reduced-motion: reduce) {
  #root .menestrel-ui .inv-aviso { animation: none; }
  #root .menestrel-ui .inv-card.inv-card--guardar { transform: none; }
}

#root .menestrel-ui .inv-slot-ghost {
  display: block;
  aspect-ratio: 1 / 1;
  width: var(--inv-casa);
  height: var(--inv-casa);
  border-radius: 6px;
  background: radial-gradient(ellipse at 30% 30%, rgba(255,255,255,0.018) 0%, transparent 65%),
    linear-gradient(160deg, rgba(40,32,17,0.95) 0%, rgba(29,22,11,0.98) 100%);
  border: 1px solid rgba(255,255,255,0.04);
  box-shadow:
    inset 0 1px 3px rgba(0,0,0,0.75),
    inset 1px 0 1px rgba(0,0,0,0.40),
    inset -1px -1px 1px rgba(255,255,255,0.025);
  position: relative;
  overflow: hidden;
}

/* Crosshatch sutil dentro do slot vazio */
#root .menestrel-ui .inv-slot-ghost::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
      45deg,
      rgba(255,255,255,0.012) 0px,
      rgba(255,255,255,0.012) 1px,
      transparent 1px,
      transparent 8px
    ),
    repeating-linear-gradient(
      -45deg,
      rgba(255,255,255,0.012) 0px,
      rgba(255,255,255,0.012) 1px,
      transparent 1px,
      transparent 8px
    );
  border-radius: 6px;
}

/* Cards preenchidos dentro da grade de slots */
#root .menestrel-ui .inv-bag-grid--slots .inv-card,
#root .menestrel-ui .loja-grid--slots .loja-it {
  width: var(--inv-casa);
  height: var(--inv-casa);
  aspect-ratio: 1 / 1;
  border-radius: 6px;
  background: linear-gradient(160deg, rgba(51,40,21,0.97) 0%, rgba(37,28,12,0.99) 100%);
  box-shadow:
    inset 0 1px 2px rgba(0,0,0,0.60),
    inset 0 -1px 1px rgba(255,255,255,0.025),
    0 0 0 1px rgba(0,0,0,0.45);
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
  position: relative;
  overflow: hidden;
}

/* Filete dourado no topo dos cards preenchidos */
#root .menestrel-ui .inv-bag-grid--slots .inv-card::after,
#root .menestrel-ui .loja-grid--slots .loja-it::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, rgba(var(--ouro-rgb),0.55) 40%, rgba(var(--ouro-rgb),0.55) 60%, transparent 100%);
  pointer-events: none;
}

/* Hover: borda dourada + glow */
#root .menestrel-ui .inv-bag-grid--slots .inv-card:hover,
#root .menestrel-ui .loja-grid--slots .loja-it:hover:not(:disabled) {
  background: linear-gradient(160deg, rgba(var(--couro-rgb),0.99) 0%, rgba(var(--couro-rgb),0.99) 100%);
  box-shadow:
    inset 0 1px 2px rgba(0,0,0,0.50),
    0 0 0 1px rgba(0,0,0,0.50),
    0 0 8px rgba(var(--ouro-rgb),0.18);
}

/* Item mágico: borda âmbar permanente */
#root .menestrel-ui .inv-bag-grid--slots .inv-card--magico,
#root .menestrel-ui .loja-grid--slots .loja-it--magico {
  border-color: rgba(var(--ouro-rgb),0.65);
}
#root .menestrel-ui .inv-bag-grid--slots .inv-card--magico::after,
#root .menestrel-ui .loja-grid--slots .loja-it--magico::after {
  background: linear-gradient(90deg, transparent 0%, rgba(var(--ouro-rgb),0.85) 40%, rgba(var(--ouro-rgb),0.85) 60%, transparent 100%);
}

/* Item esgotado na loja */
#root .menestrel-ui .loja-grid--slots .loja-it.is-esgotado {
  border-color: rgba(80,60,28,0.30);
  opacity: 0.50;
}
#root .menestrel-ui .loja-grid--slots .loja-it.is-esgotado::after { display: none; }

/* Item sem moedas suficientes: ícone vermelho */
#root .menestrel-ui .loja-grid--slots .loja-it.sem-moeda .loja-it-tile { color: rgba(195, 75, 61, 1); }

/* Ícone dentro dos cards da grade */
#root .menestrel-ui .inv-bag-grid--slots .inv-card-ic,
#root .menestrel-ui .loja-grid--slots .loja-it-tile {
  background-color: transparent;
  /* O glifo acompanha a casa: ~52% dela, a mesma proporção dos 26px em 50. */
  font-size: calc(var(--inv-casa) * 0.52);
  color: rgba(201,188,156,0.85);
}
#root .menestrel-ui .inv-bag-grid--slots .inv-card:hover .inv-card-ic,
#root .menestrel-ui .loja-grid--slots .loja-it:hover:not(:disabled) .loja-it-tile {
  color: var(--tinta);
}

/* Badge de quantidade no canto */
#root .menestrel-ui .inv-bag-grid--slots .inv-card-qty {
  position: absolute;
  bottom: 3px;
  right: 4px;
  font-size: var(--fs-2xs);
  font-family: var(--font-body);
  font-weight: 600;
  color: rgba(var(--ouro-rgb),0.90);
  line-height: 1;
  letter-spacing: 0.02em;
}

/* Pills (mágico, líquido, observação) no topo-esquerdo */
#root .menestrel-ui .inv-bag-grid--slots .inv-card-pills {
  top: 3px;
  left: 3px;
}
#root .menestrel-ui .inv-bag-grid--slots .inv-pill {
  width: 12px;
  height: 12px;
  border-radius: 2px;
  font-size: var(--fs-2xs);
}
/* O vestido continua redondo mesmo na grade compacta — é metade da
   distinção (a outra é a cor), e perdê-la aqui devolveria a confusão. */
#root .menestrel-ui .inv-bag-grid--slots .inv-pill.vst { border-radius: 50%; }

/* Barra de container na grade */
#root .menestrel-ui .inv-bag-grid--slots .inv-cont-bar {
  height: 2px;
}

/* Ocultar nome do item na grade (já fica no tooltip) */
#root .menestrel-ui .inv-bag-grid--slots .inv-card-name { display: none; }
#root .menestrel-ui .loja-grid--slots .loja-it-nome { display: none; }

/* ── Responsivo: grade encolhe junto com a tela ── */
@media (max-width: 440px) {
  #root .menestrel-ui .inv-bag-grid--slots,
  #root .menestrel-ui .loja-grid--slots {
    grid-template-columns: repeat(5, 50px);
  }
}
@media (min-width: 441px) and (max-width: 620px) {
  #root .menestrel-ui .inv-bag-grid--slots,
  #root .menestrel-ui .loja-grid--slots {
    grid-template-columns: repeat(6, 50px);
  }
}
#root .menestrel-ui .inv-card { overflow: hidden; position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; aspect-ratio: 1 / 1; padding: 6px 4px; text-align: center; cursor: pointer; width: 100%; font-family: var(--font-body); }
#root .menestrel-ui .inv-card-ic { display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
#root .menestrel-ui .inv-card-pills { position: absolute; top: 3px; left: 3px; display: flex; gap: 2px; flex-wrap: wrap; align-items: center; }

/* Chips de atributo no modal de detalhes: o NÚMERO passa a morar DENTRO do
   quadrinho do ícone, pequeno, no canto inferior direito (pedido do usuário,
   11/09/2026). Antes ficava ao lado, e cada chip ocupava o dobro da largura
   por causa disso — com 6 atributos a linha quebrava. */
/* O contexto de posicionamento é o CHIP, não o quadrinho do ícone: o
   número (.det-sec-val) é IRMÃO de .det-sec-ic-box, não filho dele. Pôr
   `position: relative` no ícone não o ancorava em nada, e o absoluto subia
   até o modal — o número foi parar no canto inferior direito da janela. */
#root .menestrel-ui .det-sec-chip { position: relative; display: inline-flex; }
/* O chip de efeito é só o ícone e abre tooltip no hover. Sem cursor `help`
   e sem contorno dourado (pedido do usuário, 11/09/2026) — o tooltip já é
   o retorno, e a moldura competia com os selos de estado.

   O realce de FOCO fica, discreto: sem ele quem navega por teclado não tem
   como saber onde está. É outra coisa do hover. */
#root .menestrel-ui .det-sec-chip--efeito:focus-visible .det-sec-ic-box {
  outline: 1px solid rgba(var(--tinta-rgb),0.45); outline-offset: 1px;
}
#root .menestrel-ui .det-sec-chip .det-sec-val {
  position: absolute; right: -3px; bottom: -3px;
  min-width: 13px; height: 13px; padding: 0 2px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: var(--fs-2xs); font-weight: 700; line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--tinta); background: #362B1A;
  border: 1px solid var(--regua-forte); border-radius: 4px;
}

/* Faísca do item mágico — marca de NATUREZA, não de estado: sem caixa, pra
   não parecer mais um selo. Fica no canto oposto aos selos. */
/* A caixa é a MESMA do selo E (.inv-pill: 14px, a 3px do topo; 12px na grade
   compacta), com o glifo centrado — assim a faísca e o E ficam na mesma
   altura (13/09/2026). */
#root .menestrel-ui .inv-faisca {
  position: absolute; top: 3px; right: 3px;
  display: inline-flex; align-items: center; justify-content: center;
  width: 14px; height: 14px;
  font-size: var(--fs-2xs); line-height: 1;
  color: var(--vivo); text-shadow: 0 0 4px rgba(var(--ouro-rgb),0.55);
  pointer-events: none;
}
#root .menestrel-ui .inv-bag-grid--slots .inv-faisca { width: 12px; height: 12px; font-size: var(--fs-2xs); }

/* A BARRA DE RESISTÊNCIA SAIU DOS ÍCONES (26/10/2026, pedido do usuário:
   "remova a linha branca que representa a resistência de um item do ícone no
   slot"). Era uma faixa branca colada no rodapé da casa, e desde que as casas
   ganharam pintura ela atravessava o desenho. O número continua no tooltip da
   casa e no painel do item, ao lado de ocupa e absorção — regras `.inv-res-*`
   removidas junto, para não ficar CSS sem dono.

   `.inv-slot` segue como contexto de posicionamento: o contador, o × e o
   rótulo da casa são absolutos dentro dela. */
#root .menestrel-ui .inv-slot { position: relative; }

/* Rodapé do card de personagem — só existe no perfil Jogador, onde o card
   tem a ação "Selecionar personagem" (ver PersonagemCard).

   Sem padding lateral próprio (12/09/2026): o `.pj-card` já reserva 17px de
   cada lado, e os 14px daqui somavam em cima disso — o botão ficava recuado
   31px enquanto retrato, nome e jogador ficavam em 17px. Era exatamente o
   "espaçamento maior que o dos outros itens do card" que o usuário viu.

   `margin-top: auto` gruda a ação no fundo, então cards de alturas
   diferentes na mesma linha alinham os botões entre si.

   O botão NÃO é mais de largura total: esticar uma pílula de 32px até a
   borda do card deixava a ação com cara de barra, e no card ativo — que
   agora ocupa a linha inteira — viraria um botão de um palmo. Pílula no
   tamanho do texto, centralizada. */
/* .pj-card-foot saiu em 17/09/2026 com o botão que ele segurava. */

/* ── Pills do item: ESTADO x INFORMAÇÃO ────────────────────────────────
   Até 11/09/2026 `.inv-pill` não tinha estilo base nenhum — nem fundo, nem
   cor. As cinco variantes (eq/vst/mag/liq/nor) saíam idênticas, distinguidas
   só pelo glifo de 8-12px, e era impossível bater o olho e saber o que está
   equipado. Pedido do usuário: "os itens equipados podem ser melhor
   sinalizados, para não confundir com os não equipados ou vestidos."

   A separação é por CATEGORIA, não por item:
     • ESTADO (equipado / vestido) — preenchido e saturado. É o que muda o
       que o personagem pode fazer, então grita.
     • INFORMAÇÃO (mágico / líquido / observação) — contorno discreto. É
       metadado; não pode competir com o estado.

   Equipado usa o ouro do tema e vestido o azul, as duas cores que o projeto
   já emprega — e são distinguíveis também por forma (o vestido é redondo),
   para não depender só de cor. */
#root .menestrel-ui .inv-pill {
  display: inline-flex; align-items: center; justify-content: center;
  width: 14px; height: 14px; border-radius: 3px;
  font-size: var(--fs-2xs); line-height: 1; flex: 0 0 auto;
  border: 1px solid transparent;
}
/* Estado — letra num selo DISCRETO.

   A primeira versão saturou tudo (ouro e azul chapados). O usuário pediu o
   contrário: "um ícone ti-letter-e no canto, e uma cor esmaecida". Faz mais
   sentido mesmo — item equipado está EM USO, não disponível, e a leitura
   natural disso é apagar, não acender. Quem tem que brilhar é o que você
   ainda pode pegar. */
/* Desde 13/09/2026 o E (ti-letter-e-small) segue a faísca do item mágico:
   sem borda e sem fundo, só o glifo — pedido do usuário. O glifo "small"
   é miúdo, daí a fonte maior que a do selo. */
#root .menestrel-ui .inv-pill.eq {
  background: transparent; border-color: transparent;
  color: var(--vivo); text-shadow: 0 0 4px rgba(var(--ouro-rgb),0.55);
  font-size: 16px; font-weight: 700;
}
/* À venda na loja (02/10/2026): a etiqueta no mesmo molde do E — só o
   glifo, sem caixa —, em pergaminho apagado: o item está travado, não em
   destaque. O card também esmaece um pouco. */
#root .menestrel-ui .inv-pill.inv-pill--venda {
  background: transparent; border-color: transparent;
  color: #D9C9A8; text-shadow: 0 0 4px rgba(0,0,0,0.7); font-size: 13px;
}
#root .menestrel-ui .inv-card:has(.inv-pill--venda) .inv-card-ic { opacity: 0.55; }
#root .menestrel-ui .inv-pill.vst {
  background: rgba(71,170,216,0.16); color: rgba(71,170,216, 0.91);
  border-color: rgba(71,170,216,0.40);
  border-radius: 50%;
  font-weight: 700;
}
/* Informação — contorno */
#root .menestrel-ui .inv-pill.mag { color: var(--vivo); border-color: rgba(var(--ouro-rgb),0.45); background: rgba(var(--ouro-rgb),0.10); }
#root .menestrel-ui .inv-pill.liq { color: #47AAD8; border-color: rgba(71,170,216,0.40); background: rgba(71,170,216,0.10); }
#root .menestrel-ui .inv-pill.nor { color: var(--tinta-2); border-color: rgba(var(--tinta3-rgb),0.40); background: rgba(var(--tinta3-rgb),0.10); }

/* O card inteiro carrega o estado — mas a regra NÃO mora aqui: o bloco de
   cards preenchidos (busque por "Cards preenchidos") usa `!important` no
   background e na borda, e `!important` vence qualquer especificidade.
   Escrever a marcação aqui compilava, casava o seletor, e não pintava nada.
   Ver o bloco "Estado do item no CARD" junto daquelas regras. */
#root .menestrel-ui .inv-card-cont { min-width: 0; background: rgba(150, 0, 0, 0.06); position: relative; overflow: hidden; cursor: pointer; }

#root .menestrel-ui .inv-cont-bar { position: absolute; bottom: 0; left: 0; right: 0; height: 3px; }
#root .menestrel-ui .inv-cont-bar > span { display: block; height: 100%; }
#root .menestrel-ui .inv-card:has(.inv-cont-bar) { padding-bottom: 9px; }
#root .menestrel-ui .modal.modal-detalhes h3.det-title { font-weight: 400; }
#root .menestrel-ui .det-actions { margin-top: 20px; display: flex; flex-direction: column; gap: 10px; }
#root .menestrel-ui .det-act-row { display: flex; flex-direction: row; flex-wrap: wrap; align-items: stretch; gap: 9px; padding: 20px 24px 0; margin: 0 -24px; border-top: 1px solid var(--regua-forte); justify-content: space-between; }
#root .menestrel-ui .det-act-row .det-act { flex: 1; min-width: 0; justify-content: center; }
/* Botões padrão (.btn-primary/.btn-ghost/.btn-danger) dentro de .det-act-row
   NÃO esticam — largura natural, alinhados pelas pontas via justify-content:
   space-between acima (igual ao .ms-footer "de verdade": ação secundária à
   esquerda, principal à direita). Cobre CompraLojaModal (Cancelar/Comprar) e
   o menu de peça equipada da ficha (Abrir/Despir) — ambos exatamente 2 botões.
   Exceção: a fileira de VÁRIOS botões do DetalhesItemModal (Equipar/Vestir/
   Transferir/Armazenar/Descartar, 1 a 4 ao mesmo tempo) não quer esticar pelas
   pontas — quer agrupar, mesmo espírito de .batalha-header-acoes. Por isso
   .modal-detalhes volta pro flex-start logo abaixo. */
#root .menestrel-ui .modal-detalhes .det-act-row { justify-content: flex-start; }

/* ⚠️ PELE LEGADA .det-act/.det-act-primary/.det-act.danger/.det-act-lbl abaixo:
   DetalhesItemModal (inventario.jsx) e CompraLojaModal (loja.jsx) foram
   migrados pra usar .btn-primary/.btn-ghost/.btn-danger (sistema único de
   botões, ver "BOTÕES — padrão único do console" mais acima), então nada
   nesses dois arquivos usa mais as regras abaixo. Mantidas sem remover
   porque não há confirmação de que nenhuma outra fase (historias.jsx,
   personagens.jsx, diario.jsx etc.) ainda referencia .det-act — checar
   antes de apagar. Os wrappers .det-act-row/.det-act-confirm/
   .det-act-confirm-btns continuam ativos (são layout, não pele de botão). */
#root .menestrel-ui .det-act { display: flex; align-items: center; justify-content: flex-start; gap: 8px; width: 100%; text-align: left; font-family: var(--font-body); line-height: 1; padding: 0 14px; height: 46px; cursor: pointer; transition: background .18s ease, color .18s ease, border-color .18s ease; }
#root .menestrel-ui .det-act i { font-size: 16px; line-height: 1; flex: 0 0 auto; }
#root .menestrel-ui .det-act .det-act-lbl { font-size: var(--fs-sm); line-height: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#root .menestrel-ui .det-act:hover { background: var(--gold); color: var(--bone); }
#root .menestrel-ui .det-act.danger { justify-content: center; }
#root .menestrel-ui .det-act.danger:hover { border-color: var(--gold); color: var(--bone); background: transparent; }
#root .menestrel-ui .det-act.det-act-cancel { justify-content: center; height: 40px; }
#root .menestrel-ui .det-act.det-act-cancel .det-act-lbl { font-size: var(--fs-sm); }
#root .menestrel-ui .det-act:disabled { cursor: not-allowed; }
#root .menestrel-ui .det-act:disabled:hover { background: transparent; color: var(--parchment-muted); border-color: var(--regua-forte); }
#root .menestrel-ui .det-act.det-act-primary:disabled, #root .menestrel-ui .det-act.det-act-primary:disabled:hover { background: var(--gold); color: var(--bone); border-color: var(--gold); }
#root .menestrel-ui .det-act.danger:disabled:hover { background: transparent; color: var(--parchment-muted); border-color: var(--parchment-dim); }
#root .menestrel-ui .det-act-divider { height: 1px; margin: 0 0; border: 0; }
#root .menestrel-ui .det-act-confirm { display: flex; flex-direction: column; gap: 10px; padding: 16px 20px; border: 1px solid #d97878; border-radius: 6px; background: rgba(217, 120, 120, .06); }
#root .menestrel-ui .det-act-confirm-title { font-family: var(--font-title); font-weight: 400; font-size: 18px; color: var(--parchment); }
#root .menestrel-ui .det-act-confirm-lbl { font-family: var(--font-body); font-size: var(--fs-base); }
#root .menestrel-ui .det-act-confirm-btns { display: flex; gap: 9px; justify-content: space-between; }
/* .det-act legado (se usado em outra fase) continua esticando via flex:1.
   Os botões padrão (.btn-primary/.btn-ghost/.btn-danger), hoje usados nos
   4 diálogos de confirmação do DetalhesItemModal, ficam em largura natural —
   o justify-content:space-between acima já alinha Cancelar/ação pelas pontas,
   igual ao .ms-footer real. */
#root .menestrel-ui .det-act-confirm-btns .det-act { flex: 1; min-width: 0; justify-content: center; }
#root .menestrel-ui .det-transf > .det-act-confirm-btns,
#root .menestrel-ui .det-armazenar > .det-act-confirm-btns { justify-content: space-between; }

/* ── Seção A — chips de atributo do item (Ocupa / Armazena / Dano / etc.) ── */
#root .menestrel-ui .det-sec-a {
  display: flex; flex-wrap: wrap; gap: 10px;
  padding: 0 0 20px;
}
#root .menestrel-ui .det-sec-chip {
  display: inline-flex; align-items: center; gap: 8px;
  font-family: var(--font-body); font-size: var(--fs-sm); color: var(--tinta);
}
/* Ícone com borda — mesmo padrão visual do btn-icon do projeto */
