#root .menestrel-ui .wiz-hab-table .wiz-mag-detail-row td, #root .menestrel-ui .wiz-attrs-table .wiz-mag-detail-row td, #root .menestrel-ui .wiz-attrs-table tbody .wiz-mag-detail-row td, #root .menestrel-ui .wiz-attrs-table tbody .wiz-mag-detail-row td:first-child, #root .menestrel-ui .wiz-attrs-table tbody .wiz-mag-detail-row td:last-child, #root .menestrel-ui .wiz-attrs-table tbody tr.wiz-mag-detail-row td, #root .menestrel-ui .wiz-grp-table tbody .wiz-mag-detail-row td, #root .menestrel-ui .wiz-grp-table tbody .wiz-mag-detail-row td:first-child, #root .menestrel-ui .wiz-grp-table tbody .wiz-mag-detail-row td:last-child, #root .menestrel-ui .wiz-grp-table tbody tr.wiz-mag-detail-row td { padding: 0 !important; background: rgba(0, 0, 0, 0.18); border-top: 0; border-bottom: 1px solid var(--regua-forte); border-left: 0; border-right: 0; text-align: left; white-space: normal; }
