#root .menestrel-ui .xp-num { font-family: var(--font-body); font-size: 32px; line-height: 1; font-weight: 700; font-variant-numeric: lining-nums tabular-nums; /* número: algarismo tabular, não Cinzel (22/10/2026) */ }
