#root .menestrel-ui .wiz-hab-step { display: flex; align-items: center; justify-content: center; width: 30px; height: 30px; padding: 0; flex-shrink: 0; background: transparent; border: none; color: var(--gold); cursor: pointer; font-size: 16px; line-height: 1; transition: background .15s ease, color .15s ease; }
#root .menestrel-ui .wiz-hab-step:hover:not(:disabled) { background: var(--gold); color: var(--bone); }
#root .menestrel-ui .wiz-hab-step:disabled { opacity: 0.3; cursor: not-allowed; }
#root .menestrel-ui .wiz-hab-step-val { min-width: 30px; text-align: center; font-weight: 400; font-size: var(--fs-sm); border-left: 1px solid var(--regua-forte); border-right: 1px solid var(--regua-forte); padding: 0 2px; line-height: 30px; user-select: none; }
#root .menestrel-ui .cofre { padding: 18px 20px; background: var(--ink-bg-2); border: 1px solid var(--regua-forte); border-radius: 6px; }
