#root .menestrel-ui .cofre-value { font-family: var(--font-body); font-size: 18px; font-weight: 500; color: var(--parchment); padding: 2px 10px; min-width: 56px; text-align: center; }
#root .menestrel-ui .cofre-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
#root .menestrel-ui .cofre-moeda { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 14px 8px; border: 1px solid var(--regua-forte); border-radius: 6px; }
#root .menestrel-ui .cofre-coin { width: 44px; height: 44px; border-radius: 6px; display: grid; place-items: center; font-family: var(--font-body); font-weight: 700; font-size: var(--fs-base); color: rgba(0, 0, 0, 0.6); box-shadow:
