#root .menestrel-ui .batalha-mng-page-body::-webkit-scrollbar { width: 8px; height: 8px; }
#root .menestrel-ui .batalha-mng-page-body::-webkit-scrollbar-track { background: transparent; }
#root .menestrel-ui .batalha-mng-page-body::-webkit-scrollbar-thumb { background: var(--rule-strong); border-radius: 6px; }

/* ── FichaPersonagem: mesmo molde de header de página (cv-mng/loja-mng-v3/
