#root .menestrel-ui .fp-montaria-desc { font-family: var(--font-body); font-size: var(--fs-sm); line-height: 1.55; color: var(--foreground); margin: 0 0 8px; }
#root .menestrel-ui .fp-info-grid--5 { grid-template-columns: repeat(5, 1fr); }

