/* ── Tubos ── */

/* ── Medalhões ── */
#root .menestrel-ui .fp-medalhoes { display: grid; grid-template-columns: repeat(auto-fill, minmax(86px, 1fr)); justify-items: center; gap: 12px 10px; }
#root .menestrel-ui .fp-medalhao { width: 86px; height: 86px; position: relative; border-radius: 50%; outline: none; }
