/* o canal (anel de 34 a 40px do centro) recorta o líquido até a porcentagem */
#root .menestrel-ui .fp-medalhao-canal { position: absolute; inset: 0; z-index: 1; border-radius: 50%;
  -webkit-mask: conic-gradient(#000 calc(var(--p) * 1%), transparent 0), radial-gradient(circle, transparent 33.5px, #000 34px, #000 40px, transparent 40.5px);
  -webkit-mask-composite: source-in;
  mask: conic-gradient(#000 calc(var(--p) * 1%), transparent 0), radial-gradient(circle, transparent 33.5px, #000 34px, #000 40px, transparent 40.5px);
  mask-composite: intersect; }
#root .menestrel-ui .fp-medalhao-liq { position: absolute; inset: 0; border-radius: 50%;
  background: radial-gradient(circle, #24103F 33.5px, #5E2FA0 35.6px, #9A74D8 37px, #5E2FA0 38.4px, #24103F 40.5px), #5E2FA0;
  animation: fp-corre 9s linear infinite; animation-delay: var(--a); }
@keyframes fp-corre { to { transform: rotate(360deg); } }
#root .menestrel-ui .fp-medalhao-liq::after { border-radius: 50%; background-size: 220% 220%; }
#root .menestrel-ui .fp-medalhao-liq > i { position: absolute; left: 50%; top: 50%; width: var(--t); height: var(--t); margin: calc(var(--t) / -2) 0 0 calc(var(--t) / -2);
  border-radius: 50%; opacity: 0; background: radial-gradient(circle at 35% 35%, rgba(255,255,255,.6), rgba(255,255,255,.14) 60%, transparent 70%);
  border: 1px solid rgba(255,255,255,.3); animation: fp-orbita var(--d) ease-in-out infinite; animation-delay: var(--a2); }
