  100% { transform: rotate(calc(var(--g) + 80deg)) translateX(36.8px); opacity: 0; } }
#root .menestrel-ui .fp-medalhao-face { position: absolute; inset: 10px; z-index: 3; border-radius: 50%; overflow: hidden; display: grid; place-items: center;
  background: radial-gradient(circle at 50% 45%, #2A2015, #110B06 80%); }
#root .menestrel-ui .fp-medalhao-face::after { content: ""; position: absolute; inset: 0; border-radius: 50%; box-shadow: inset 0 0 10px rgba(0,0,0,.75); }
